import sys

MOD = 998244353

def mod_pow(base, exp, mod):
    result = 1
    while exp > 0:
        if (exp & 1) != 0:
            result = result * base % mod
        base = base * base % mod
        exp >>= 1
    return result

def mod_inverse(a, m):
    return mod_pow(a, m - 2, m)

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    k = int(input_data[2])

    S = [[0] * (k + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        S[i][i] = 1
        S[i][0] = 0
    for i in range(2, k + 1):
        for j in range(1, i + 1):
            S[i][j] = (S[i - 1][j] * j % MOD + S[i - 1][j - 1]) % MOD

    m_inv = mod_inverse(m, MOD)
    dp = [0] * (k + 1)
    dp[0] = 1
    limit = min(n, k)
    for i in range(1, limit + 1):
        dp[i] = dp[i - 1] * (n - i + 1) % MOD

    answer = 0
    for i in range(1, limit + 1):
        answer = (answer + dp[i] * mod_pow(m_inv, i, MOD) % MOD * S[k][i] % MOD) % MOD

    print(answer)

if __name__ == "__main__":
    main()

